import type { ChatSession, Entitlements, StoredMessage } from './schemas';
import type { ChatEvent } from './sse';

/**
 * Everything the chat UI needs from a server. The real implementation talks to
 * the Kwala services; a development-only mock implements the same interface.
 */
export interface ChatBackend {
  /** Idempotent: the id is generated by the client, so a retry returns the same session. */
  createSession(id: string): Promise<ChatSession>;
  listSessions(): Promise<ChatSession[]>;
  getMessages(sessionId: string): Promise<StoredMessage[]>;
  deleteSession(sessionId: string): Promise<void>;
  getEntitlements(): Promise<Entitlements | null>;
  /**
   * Sends one user turn and reports the streamed answer through `onEvent`.
   * Resolves when the stream ends. Throws ChatError on a refusal or failure.
   */
  streamChat(args: {
    sessionId: string;
    message: string;
    signal: AbortSignal;
    onEvent: (event: ChatEvent) => void;
  }): Promise<void>;
}
